package gate

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

// K5Corpus is the K5 synthetic corpus (CONTRACT §15 K5.1; ADR-0030),
// generated by internal/synth (gencorpus --set k5).
const K5Corpus = "testdata/corpus-k5"

// K5SabotageDeps is, for each checker sabotage rule of the C7–C9 checks
// (build tag cp_sabotage_<rule>, CONTRACT §15 K5.1), the set of K5 corpus
// labels whose histories must stop matching their expected.json when that
// rule is broken — and no others. Written from the rules
// (internal/checker/c5c7.go, c8c9.go) and the plants of
// internal/synth/k5.go, before any K5 sabotage build ran:
//
//   - session_setting: no SHOW is compared with its connection's SETs; only
//     the setting-lost plants differ (every other SHOW returns its SET).
//   - prepared_statement: no EXECUTE after an ok PREPARE is judged: the
//     prepared-26000 and prepared-row plants.
//   - notify_resume: a NOTIFY that is judged and missed is not reported:
//     the not-resumed plants lose their anomaly; reconnect-window plants
//     report only observations and do not change.
//   - notify_anchor: neither the fault-window overlap nor the recovery
//     anchor excuses a miss, so S19's reconnect-window misses become
//     notify-not-resumed: the reconnect-window plants (observation only)
//     and the not-resumed plants never/after-second, whose expectation also
//     holds notify-window-loss observations (the not-resumed-one plant has
//     none and does not change; one failing entry fails the label).
//   - fair_share: no storm window is judged for starvation.
//   - overload_failover: no server change is judged.
//   - planned_failover: errors in judged switchover windows are not
//     reported; the unbuffered plants' observations are made before the
//     rule and do not change.
//   - buffer_guard: every F6 window is judged as buffered, so the
//     unbuffered plants' errors become planned-failover-error; the
//     planned-failover-error plants have no error outside their first
//     (judged) window, and clean G8 histories none at all.
//   - cdc_gap, cdc_phantom, cdc_order: the plants of that class only.
//   - cdc_duplicate_bound: the bound becomes lsn < flushed; the
//     duplicate-boundary plants re-deliver exactly at the confirmed flush
//     and are missed (the duplicate-below plant is still reported; one
//     failing entry fails the label).
var K5SabotageDeps = map[string][]string{
	"session_setting":     {"session-setting-lost"},
	"prepared_statement":  {"prepared-statement-lost"},
	"notify_resume":       {"notify-not-resumed"},
	"notify_anchor":       {"notify-not-resumed", "notify-reconnect-window"},
	"fair_share":          {"fair-share-starvation"},
	"overload_failover":   {"overload-failover"},
	"planned_failover":    {"planned-failover-error"},
	"buffer_guard":        {"planned-failover-unbuffered"},
	"cdc_gap":             {"cdc-gap"},
	"cdc_phantom":         {"cdc-phantom"},
	"cdc_order":           {"cdc-order"},
	"cdc_duplicate_bound": {"cdc-duplicate"},
}

// K5Classes are the classes K5.1 requires planted (CONTRACT §15 K5.1) and
// the two observations the K5 completions add (ADR-0029, ADR-0030).
var K5Classes = []string{
	"session-setting-lost", "prepared-statement-lost", "notify-not-resumed", "fair-share-starvation", "overload-failover",
	"planned-failover-error", "cdc-gap", "cdc-phantom", "cdc-duplicate", "cdc-order",
	"notify-window-loss", "planned-failover-unbuffered",
}

// K5Families are the corpus families with clean histories (W5–W8 and G8).
var K5Families = []string{"w5k", "w6k", "w7k", "w8k", "g8k"}

// ResultsFile is dir/results.jsonl, or its compressed copy
// dir/results.jsonl.zst when only that exists (K5 evidence, P25).
func ResultsFile(dir string) string {
	p := filepath.Join(dir, "results.jsonl")
	if _, err := os.Stat(p); err != nil {
		if _, err := os.Stat(p + ".zst"); err == nil {
			return p + ".zst"
		}
	}
	return p
}

// SabotageRules lists a dependency map's rules in order.
func SabotageRules(deps map[string][]string) []string {
	rules := make([]string, 0, len(deps))
	for r := range deps {
		rules = append(rules, r)
	}
	sort.Strings(rules)
	return rules
}

// CheckSabotage compares a sabotage run's failing labels with deps[rule].
func CheckSabotage(deps map[string][]string, rule, corpus, results string) (string, []string) {
	failing, p := K2Failing(corpus, results)
	var got []string
	for l := range failing {
		got = append(got, l)
	}
	sort.Strings(got)
	if setOf(got) != setOf(deps[rule]) {
		p = append(p, fmt.Sprintf("sabotage %s fails labels {%s}, expected exactly {%s}", rule, setOf(got), setOf(deps[rule])))
	}
	return fmt.Sprintf("%s: failing labels {%s}", rule, setOf(got)), p
}
